// Supabase config is stored in localStorage — no hardcoded credentials.
// Users enter their own project URL and anon key on first launch.
const SUPABASE_CONFIG_STORAGE_KEY = "flashcards_supabase_config";

function loadSupabaseConfig() {
  try {
    const raw = localStorage.getItem(SUPABASE_CONFIG_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function saveSupabaseConfig(url, key) {
  localStorage.setItem(SUPABASE_CONFIG_STORAGE_KEY, JSON.stringify({ url: url.trim(), key: key.trim() }));
}

function clearSupabaseConfig() {
  localStorage.removeItem(SUPABASE_CONFIG_STORAGE_KEY);
}

let supabaseClient = null;
// Tracks whether a real user session is active, so background auto-sync only
// fires for signed-in users (and never tries to push while logged out).
let isSignedIn = false;

// Returns a REASON, not a boolean. The two failures it used to conflate need
// opposite responses: "no-config" is a first run and the setup form is correct;
// "no-library" is a configured device whose CDN fetch for supabase-js failed,
// and showing that user the setup form tells them their project is missing when
// it isn't — then offers them a button that deletes it. The developer never saw
// this because localhost keeps the script warm and unregisters the worker.
function initSupabaseClient() {
  const config = loadSupabaseConfig();
  if (!config?.url || !config?.key) return "no-config";
  if (!window.supabase) return "no-library";
  try {
    supabaseClient = window.supabase.createClient(config.url, config.key);
  } catch (error) {
    // A malformed URL or key that passed the setup form's shape check can throw
    // here. Treated as "no client" rather than allowed to abort boot.
    console.warn("Could not create the Supabase client", error);
    supabaseClient = null;
    return "no-library";
  }
  preconnectToStorageOrigin(config.url);
  return "ok";
}

// index.html can only preconnect to cdn.jsdelivr.net — every user brings their
// own Supabase project, so the storage origin isn't known until the config is
// read. Without this the first image of a session pays DNS + TLS on top of its
// download, which is exactly the request the reader is waiting on.
function preconnectToStorageOrigin(url) {
  try {
    const origin = new URL(url).origin;
    if (document.querySelector(`link[rel="preconnect"][href="${CSS.escape(origin)}"]`)) return;
    const link = document.createElement("link");
    link.rel = "preconnect";
    link.href = origin;
    link.crossOrigin = "anonymous";
    document.head.appendChild(link);
  } catch {
    // A malformed configured URL is already handled above; nothing to warm.
  }
}

// supabase-js is a blocking <script> before this file, so if it were coming at
// all it would already be here — except when the browser gave up on it early,
// or a slow CDN answered after the parser moved on. Cheap to keep looking for a
// few seconds before declaring failure, and free when it's already loaded.
async function waitForSupabaseLibrary(timeoutMs = 8000) {
  if (window.supabase) return true;
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 200));
    if (window.supabase) return true;
  }
  return false;
}

// Re-fetch supabase-js by hand. The original <script> has already failed and
// will not retry itself, so "Try again" has to actually go and get it — a bare
// location.reload() would re-run the same blocked request through the same
// blocked path and look identical to doing nothing.
function reloadSupabaseLibrary() {
  return new Promise((resolve) => {
    if (window.supabase) return resolve(true);
    const script = document.createElement("script");
    script.src = "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.112.2";
    script.async = true;
    script.onload = () => resolve(Boolean(window.supabase));
    script.onerror = () => resolve(false);
    document.head.appendChild(script);
  });
}

// ── Deferred third-party libraries ──────────────────────────────────────────
//
// index.html used to load 5.8MB of blocking CDN JavaScript before app.js, and
// every listener in this file attaches at module scope — so until all of that
// had downloaded AND executed, the whole UI was painted and completely inert.
// Measured cold: controls on screen at 56ms, listeners live at 5421ms. That is
// the real reason the app "felt laggy": the first press of a session genuinely
// did nothing. (The boot-click queue in index.html covers that window by
// replaying the press; it is a mitigation, not a fix.)
//
// Six of those libraries — mermaid (3.3MB on its own), jszip, nomnoml+graphre
// and turndown+its gfm plugin — are render-, import- or export-only. They now
// load from here instead.
//
// Why injected rather than `defer`: deferred scripts still block
// DOMContentLoaded, and initToolbars — which wires the ☰ drawer that every
// toolbar action lives behind — waits on that event, so `defer` would have
// moved the stall rather than removed it. `async` would not block it, but
// loses the ordering graphre→nomnoml and turndown→its plugin both require.
//
// What stays blocking in index.html: dompurify, marked, prism and katex (the
// first render needs them) and supabase-js (bootApp needs it).
//
// OFFLINE CONTRACT: these URLs must stay byte-identical to the entries in
// sw.js's CDN_ASSETS. The worker precaches them at install and serves
// cdn.jsdelivr.net cache-first, so an injected <script> for the same URL is
// still answered from the cache with no connection. A typo here doesn't fail
// loudly — it quietly turns "works offline" into "worked offline on the
// machine it was tested on".
const CDN_BASE = "https://cdn.jsdelivr.net/npm/";
const LIB_URLS = {
  mermaid: `${CDN_BASE}mermaid@10.9.1/dist/mermaid.min.js`,
  jszip: `${CDN_BASE}jszip@3.10.1/dist/jszip.min.js`,
  graphre: `${CDN_BASE}graphre/dist/graphre.js`,
  nomnoml: `${CDN_BASE}nomnoml/dist/nomnoml.js`,
  turndown: `${CDN_BASE}turndown@7.1.2/dist/turndown.js`,
  turndownGfm: `${CDN_BASE}turndown-plugin-gfm@1.0.2/dist/turndown-plugin-gfm.js`
};

// url -> Promise<boolean>. Cached by URL so concurrent callers (a note with
// twelve diagrams in it) share one <script>, and so a failed load isn't retried
// on a loop — it resolves false and the caller degrades.
const loadedScripts = new Map();

function loadScriptOnce(url) {
  let pending = loadedScripts.get(url);
  if (pending) return pending;
  pending = new Promise((resolve) => {
    const script = document.createElement("script");
    script.src = url;
    script.async = true;
    script.onload = () => resolve(true);
    script.onerror = () => {
      // Drop the rejection from the cache so a later attempt (back online, or
      // after the worker's CDN repair pass) can succeed.
      loadedScripts.delete(url);
      console.warn("Could not load", url);
      resolve(false);
    };
    document.head.appendChild(script);
  });
  loadedScripts.set(url, pending);
  return pending;
}

async function ensureMermaid() {
  if (typeof mermaid !== "undefined") return true;
  if (!(await loadScriptOnce(LIB_URLS.mermaid))) return false;
  // setTheme() ran at boot and its configureMermaid() call was a no-op with no
  // library to configure. Apply the current theme now, or the first diagram
  // would draw in mermaid's own default palette.
  configureMermaid(currentThemeId());
  return true;
}

async function ensureJsZip() {
  if (window.JSZip) return true;
  return loadScriptOnce(LIB_URLS.jszip);
}

async function ensureNomnoml() {
  if (typeof nomnoml !== "undefined") return true;
  // Sequential, not Promise.all: nomnoml reads graphre off the global at
  // evaluation time.
  if (!(await loadScriptOnce(LIB_URLS.graphre))) return false;
  return loadScriptOnce(LIB_URLS.nomnoml);
}

async function ensureTurndown() {
  if (typeof TurndownService !== "undefined") return true;
  if (!(await loadScriptOnce(LIB_URLS.turndown))) return false;
  // The gfm plugin augments TurndownService, so it must come second. Its
  // absence is survivable (tables and strikethrough convert less well), so a
  // failure here doesn't fail the whole thing.
  await loadScriptOnce(LIB_URLS.turndownGfm);
  return true;
}

// Called once the app is interactive. The ensureX() guards above are the
// correctness backstop, but they make the caller wait; warming the libraries
// while the user is still reading their first card means that by the time
// anyone renders a diagram, runs a backup or pastes rich text, the library is
// already there. Idle-time and unawaited, so it cannot get in front of
// anything the user is doing.
//
// This also covers htmlToMarkdown's paste path, which reads clipboardData
// synchronously and so genuinely cannot await a loader mid-event.
let deferredLibrariesWarmed = false;
function warmDeferredLibraries() {
  if (deferredLibrariesWarmed) return;
  deferredLibrariesWarmed = true;
  const warm = () => {
    ensureMermaid();
    ensureJsZip();
    ensureNomnoml();
    ensureTurndown();
  };
  // Held back a couple of seconds and THEN made to wait for an idle moment.
  // Both halves matter: the app is still rendering its first deck when this is
  // armed, and requestIdleCallback alone would happily fire during one of
  // boot's IndexedDB awaits — dropping a 3.3MB mermaid parse straight into the
  // window this whole change exists to clear. Anyone who reaches a diagram
  // before then simply loads it through the ensureX() guard instead.
  setTimeout(() => {
    if (typeof requestIdleCallback === "function") requestIdleCallback(warm, { timeout: 5000 });
    else warm();
  }, 2000);
}

// Reads the session straight from local storage — no network — so a user who
// has signed in at least once can keep using the app while offline.
async function getCachedSession() {
  if (!supabaseClient) return null;
  try {
    const { data } = await supabaseClient.auth.getSession();
    return data?.session ?? null;
  } catch (error) {
    console.warn("Could not read cached session", error);
    return null;
  }
}

// Proof that the requests this sync is about to make will actually carry THIS
// user's identity — not just that the app once saw a session (`isSignedIn`).
//
// This is the single most destructive failure mode the app has. Every table is
// RLS-scoped to `auth.uid()`, so a request that reaches Supabase without a valid
// user token is not rejected: it succeeds and matches nothing. The reconcile
// then reads an empty deck list as "every deck was deleted on another device",
// deletes the local library, and (before the change alongside this one) wrote
// tombstones for all of it — losing the user's decks on every device at once.
//
// `isSignedIn` cannot rule that out. It's a boolean set from a CACHED session,
// so it stays true after a refresh token expires or a refresh fails. getSession()
// is the check that matters: it refreshes an expired access token when it can,
// and returns null when it can't — which is precisely "your next query would run
// as nobody". No network cost in the common case (a live token is returned from
// local storage as-is).
async function verifiedCloudUserId() {
  if (!supabaseClient) return null;
  try {
    const { data, error } = await supabaseClient.auth.getSession();
    if (error) return null;
    const session = data?.session;
    // An access token that has already expired means the queries below would go
    // out unauthenticated (or be rejected outright). getSession normally
    // refreshes it for us; if it handed one back anyway, don't trust it.
    if (!session?.user?.id || !session?.access_token) return null;
    if (session.expires_at && Number(session.expires_at) * 1000 <= Date.now()) return null;
    return String(session.user.id);
  } catch (error) {
    console.warn("Could not verify the signed-in user", error);
    return null;
  }
}

let explicitLogout = false;

// Raw provider strings were shown verbatim, which is fine for "Invalid login
// credentials" and useless for the rest. "Failed to fetch" reads like a bug in
// the app; "Invalid API key" is a truthful message about a cause the user has no
// reason to connect to the key they pasted on a different screen. The sync path
// already translates the network case (see writeStyleToCloud) — this is the same
// judgement applied where people actually hit it.
function describeAuthError(error) {
  const message = String(error?.message || error || "Something went wrong");
  if (!navigator.onLine || /failed to fetch|networkerror|load failed|timed out/i.test(message)) {
    return "Couldn't reach your Supabase project — check your connection, then try again.";
  }
  if (/invalid api key/i.test(message)) {
    return "This project's anon key isn't valid. Use “Change Supabase project” below and paste it again.";
  }
  if (/email not confirmed/i.test(message)) {
    return "This email hasn't been confirmed yet — check your inbox for the confirmation link.";
  }
  if (/email logins are disabled|signups not allowed|signup is disabled/i.test(message)) {
    return "This Supabase project has email sign-in turned off. Enable it under Authentication → Providers → Email.";
  }
  return message;
}

// Every cloud data call is wrapped in withTimeout; these three never were, and
// they are the ones a user is actively waiting on. On a network that accepts a
// connection and then answers nothing — the exact failure the service worker's
// whole design exists for — the promise never settles, so the submit button
// stays disabled with no error and no spinner, and only a reload recovers.
const AUTH_TIMEOUT_MS = 20000;

async function handleLogin(email, password) {
  const { data, error } = await withTimeout(
    supabaseClient.auth.signInWithPassword({ email, password }),
    AUTH_TIMEOUT_MS,
    "sign in"
  );
  if (error) throw error;
  return data.user;
}

// Returns what actually happened, because "no error" does not mean "signed in".
// With Supabase's default "Confirm email" ON — a dashboard setting the app can't
// see and that supabase_setup.sql only mentions in a closing comment — signUp
// resolves with a user and a NULL session and no error at all. The old code
// returned data.user, the caller treated that as success, no auth event fired,
// and the button simply re-enabled: pressing "Create Account" did visibly
// nothing. Supabase also deliberately obfuscates an already-registered address
// by returning a fake user with an empty `identities` array, which looked
// identical.
async function handleSignup(email, password) {
  const { data, error } = await withTimeout(
    supabaseClient.auth.signUp({
      email,
      password,
      // Without this, a confirmation mail points at the project's dashboard Site
      // URL, which defaults to http://localhost:3000 — a dead page on the
      // user's own machine. Sending them back where they signed up from is the
      // only value that's right for every deployment.
      options: { emailRedirectTo: location.href.split("#")[0] }
    }),
    AUTH_TIMEOUT_MS,
    "create account"
  );
  if (error) throw error;

  if (data?.session) return { outcome: "signed-in", user: data.user };
  if (data?.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {
    return { outcome: "already-registered", user: data.user };
  }
  return { outcome: "confirm-email", user: data?.user || null };
}

async function handleLogout() {
  explicitLogout = true;
  // The signed-in uid outlives the session unless it is cleared here: it is
  // what styleSettingsRowId() and getQuickNotesDeckId() resolve against, so
  // leaving it behind pointed the next account's style row and quick-notes deck
  // at the previous user.
  try { localStorage.removeItem(LAST_USER_STORAGE_KEY); } catch (_) {}
  // Unscoped and replayed on the next reconcile by whoever is signed in then —
  // on a shared device that uploaded one user's style into another's row. The
  // quick-note queues are deck-scoped and self-discard; this one never was.
  try { localStorage.removeItem(PENDING_STYLE_KEY); } catch (_) {}
  if (supabaseClient) {
    try {
      await withTimeout(supabaseClient.auth.signOut(), AUTH_TIMEOUT_MS, "sign out");
    } catch (error) {
      // Offline sign-out still clears the local session below via the listener.
      console.warn("Sign-out network call failed (continuing locally)", error);
    }
  }
}

// One switch for the four mutually exclusive boot states, so a new one can't be
// added by remembering to hide three things somewhere else and forgetting one.
function showBootScreen(which) {
  const overlays = {
    setup: "setupOverlay",
    login: "loginOverlay",
    library: "offlineBootOverlay"
  };
  for (const [name, id] of Object.entries(overlays)) {
    const node = document.getElementById(id);
    if (node) node.hidden = name !== which;
  }
  const shell = document.querySelector(".app-shell");
  if (shell) shell.hidden = which !== "app";
  const logout = document.getElementById("logoutBtn");
  if (logout) logout.hidden = which !== "app";
}

function showSetupScreen() { showBootScreen("setup"); }
function showLoginScreen() { showBootScreen("login"); }
function showAuthenticatedUI() { showBootScreen("app"); }
function showLibraryFailedScreen() { showBootScreen("library"); }


// A deck's `category` is a "/"-delimited folder path (e.g. "Math/Calculus"):
// each segment is a folder, nesting is arbitrary depth. Legacy flat categories
// (no "/") are simply single-segment paths, so this stays backward compatible.
const FOLDER_SEP = "/";

// Splits a category into its trimmed, non-empty folder segments.
function folderSegments(value) {
  return String(value || "")
    .split(FOLDER_SEP)
    .map((segment) => segment.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

function normalizeDeckCategory(value) {
  const segments = folderSegments(value);
  return segments.length ? segments.join(FOLDER_SEP) : defaultDeckCategory;
}

// True when `path` is `ancestor` itself or nested beneath it.
function isCategoryUnder(path, ancestor) {
  const p = normalizeDeckCategory(path);
  const a = normalizeDeckCategory(ancestor);
  return p === a || p.startsWith(a + FOLDER_SEP);
}

// Rewrites a category whose path is `fromPath` (or nested under it) so its
// `fromPath` prefix becomes `toPath`; returns it unchanged otherwise.
function rewriteCategoryPrefix(category, fromPath, toPath) {
  const current = normalizeDeckCategory(category);
  const from = normalizeDeckCategory(fromPath);
  if (current === from) return normalizeDeckCategory(toPath);
  if (current.startsWith(from + FOLDER_SEP)) {
    return normalizeDeckCategory(toPath + current.slice(from.length));
  }
  return current;
}

function categorySortValue(value) {
  const category = normalizeDeckCategory(value);
  return category === defaultDeckCategory ? "" : category.toLowerCase();
}

// ── Empty-folder registry ──────────────────────────────────────────────────
// Folders only exist implicitly, as prefixes of deck categories — so a folder
// with no decks yet has nowhere to live. This device-local list keeps such
// freshly-created (or emptied) folders visible until a deck lands in them; once
// one does, the folder persists everywhere via that deck's synced category.
const KNOWN_FOLDERS_KEY = "flashcards_folders_v1";
const COLLAPSED_FOLDERS_KEY = "flashcards_folder_collapsed_v1";

function readKnownFolders() {
  try {
    const list = JSON.parse(localStorage.getItem(KNOWN_FOLDERS_KEY) || "[]");
    return Array.isArray(list) ? list.map(normalizeDeckCategory).filter((p) => p !== defaultDeckCategory) : [];
  } catch (error) {
    console.warn("Could not read known folders", error);
    return [];
  }
}

function writeKnownFolders(list) {
  const unique = Array.from(new Set((list || []).map(normalizeDeckCategory)))
    .filter((p) => p !== defaultDeckCategory);
  try { localStorage.setItem(KNOWN_FOLDERS_KEY, JSON.stringify(unique)); } catch (_) {}
  return unique;
}

function addKnownFolder(path) {
  const normalized = normalizeDeckCategory(path);
  if (normalized === defaultDeckCategory) return;
  writeKnownFolders([...readKnownFolders(), normalized]);
}

// Forgets a folder and every subfolder under it: drops them from the
// known-folder registry and from the collapsed/expanded UI state, and lifts
// the Folder-view cwd out if it pointed inside. A folder has no record of its
// own — it is a deck-category prefix plus a registry entry — so once its decks
// are gone this is the only thing still holding it on screen, which is exactly
// how a deleted folder used to linger as an empty "0 decks" shell.
function forgetFolderTree(path) {
  const target = normalizeDeckCategory(path);
  if (target === defaultDeckCategory) return;

  writeKnownFolders(readKnownFolders().filter((p) => !isCategoryUnder(p, target)));

  const prune = (set) => {
    const next = new Set();
    set.forEach((p) => { if (!isCategoryUnder(p, target)) next.add(p); });
    return next;
  };
  writeCollapsedFolders(prune(readCollapsedFolders()));
  writeExpandedFolders(prune(readExpandedFolders()));

  if (state.myDecksCwd && isCategoryUnder(state.myDecksCwd, target)) {
    setMyDecksCwd(folderSegments(target).slice(0, -1).join(FOLDER_SEP));
  }
}

function readCollapsedFolders() {
  try {
    const list = JSON.parse(localStorage.getItem(COLLAPSED_FOLDERS_KEY) || "[]");
    return new Set(Array.isArray(list) ? list.map(normalizeDeckCategory) : []);
  } catch (error) {
    console.warn("Could not read collapsed folders", error);
    return new Set();
  }
}

function writeCollapsedFolders(set) {
  try { localStorage.setItem(COLLAPSED_FOLDERS_KEY, JSON.stringify(Array.from(set))); } catch (_) {}
}

// Folders are FOLDED BY DEFAULT: a folder is expanded only if its path is in this
// set (the inverse of a "collapsed" list), so a fresh library shows everything
// folded. Supersedes COLLAPSED_FOLDERS_KEY for the tree view.
const EXPANDED_FOLDERS_KEY = "flashcards_folder_expanded_v1";

function readExpandedFolders() {
  try {
    const list = JSON.parse(localStorage.getItem(EXPANDED_FOLDERS_KEY) || "[]");
    return new Set(Array.isArray(list) ? list.map(normalizeDeckCategory) : []);
  } catch (error) {
    console.warn("Could not read expanded folders", error);
    return new Set();
  }
}

function writeExpandedFolders(set) {
  try { localStorage.setItem(EXPANDED_FOLDERS_KEY, JSON.stringify(Array.from(set))); } catch (_) {}
}

function isFolderCollapsed(path) {
  return !readExpandedFolders().has(normalizeDeckCategory(path));
}

// ── My Decks view + display preferences (persisted per device) ──────────────
const MYDECKS_VIEW_KEY = "flashcards_mydecks_view_v1";       // grid | folder | tree
const MYDECKS_DISPLAY_KEY = "flashcards_mydecks_display_v1"; // tiles | list
const MYDECKS_CWD_KEY = "flashcards_mydecks_cwd_v1";         // Folder-view path
const MYDECKS_SORT_KEY = "flashcards_mydecks_sort_v1";
const MYDECKS_SORT_OPTIONS = ["recent", "title-asc", "title-desc", "updated-desc", "created-desc", "size-desc"];

function setMyDecksView(view) {
  if (!["grid", "folder", "tree"].includes(view)) return;
  state.myDecksView = view;
  try { localStorage.setItem(MYDECKS_VIEW_KEY, view); } catch (_) {}
}

function setMyDecksDisplay(display) {
  if (!["tiles", "list"].includes(display)) return;
  state.myDecksDisplay = display;
  try { localStorage.setItem(MYDECKS_DISPLAY_KEY, display); } catch (_) {}
}

function setMyDecksSort(sort) {
  if (!MYDECKS_SORT_OPTIONS.includes(sort)) return;
  state.myDecksSort = sort;
  try { localStorage.setItem(MYDECKS_SORT_KEY, sort); } catch (_) {}
}

function setMyDecksCwd(path) {
  state.myDecksCwd = normalizeDeckCategory(path) === defaultDeckCategory ? "" : normalizeDeckCategory(path);
  try { localStorage.setItem(MYDECKS_CWD_KEY, state.myDecksCwd); } catch (_) {}
}

// Builds a nested folder tree from a set of category paths and the decks that
// carry them. Each node: { name, path, children:Map<name,node>, decks:[] }.
// `deckEntries` is an array of { deck, kind } where kind is "local"|"cloud".
function buildFolderTree(deckEntries = [], extraFolders = []) {
  const root = { name: "", path: "", children: new Map(), decks: [] };
  const ensure = (path) => {
    const segments = folderSegments(path);
    let node = root;
    let acc = "";
    segments.forEach((segment) => {
      acc = acc ? acc + FOLDER_SEP + segment : segment;
      if (!node.children.has(segment)) {
        node.children.set(segment, { name: segment, path: acc, children: new Map(), decks: [] });
      }
      node = node.children.get(segment);
    });
    return node;
  };
  // Uncategorized decks live at the tree root so they aren't buried in a folder.
  extraFolders.forEach((path) => ensure(path));
  deckEntries.forEach((entry) => {
    const category = normalizeDeckCategory(entry.deck.category);
    const node = category === defaultDeckCategory ? root : ensure(category);
    node.decks.push(entry);
  });
  return root;
}

function categoriesFromDecks(decks = [], extraCategories = []) {
  return Array.from(new Set([
    defaultDeckCategory,
    ...extraCategories.map(normalizeDeckCategory),
    ...(decks || []).map((deck) => normalizeDeckCategory(deck.category))
  ])).sort((a, b) => categorySortValue(a).localeCompare(categorySortValue(b)));
}

function setKnownWebDeckCategories(categories = []) {
  webDeckCategories = categoriesFromDecks([], categories);
  return webDeckCategories;
}

async function refreshKnownWebDeckCategories() {
  if (!supabaseClient) return webDeckCategories;
  const { data, error } = await supabaseClient
    .from("decks")
    .select("category");
  if (error) throw error;
  return setKnownWebDeckCategories(categoriesFromDecks(data || []));
}

async function chooseDeckCategory(currentCategory = defaultDeckCategory) {
  try {
    await refreshKnownWebDeckCategories();
  } catch (error) {
    console.warn("Could not load deck categories", error);
  }

  return new Promise((resolve) => {
    const modal = document.createElement("section");
    modal.className = "category-choice-modal";
    modal.setAttribute("aria-label", "Choose deck category");

    const shell = document.createElement("div");
    shell.className = "category-choice-shell";
    shell.innerHTML = `
      <div class="category-choice-head">
        <div>
          <h2>Deck Category</h2>
          <p>Choose an existing category or create a new one.</p>
        </div>
        <button type="button" data-category-cancel aria-label="Close category editor">&#215;</button>
      </div>
      <label class="category-choice-field">
        <span>Category</span>
        <select data-category-select></select>
      </label>
      <label class="category-choice-field" data-category-new-field hidden>
        <span>New category</span>
        <input type="text" data-category-new autocomplete="off" spellcheck="false">
      </label>
      <div class="category-choice-actions">
        <button type="button" data-category-cancel>Cancel</button>
        <button type="button" data-category-save>Apply</button>
      </div>
    `;

    const select = shell.querySelector("[data-category-select]");
    // Offer every folder that actually exists, not just the ones the cloud knows
    // about: the local library's own categories and the known-folder registry
    // (which is where empty folders live). Without these the picker was just
    // "Uncategorized" + "New category" whenever Supabase was unreachable or the
    // folder had only ever existed on this device — so choosing an existing
    // folder was impossible offline.
    categoriesFromDecks(readLocalDeckIndex(), [
      ...webDeckCategories,
      ...readKnownFolders(),
      currentCategory
    ]).forEach((category) => {
      const option = document.createElement("option");
      option.value = category;
      option.textContent = category;
      select.appendChild(option);
    });
    const newOption = document.createElement("option");
    newOption.value = "__new__";
    newOption.textContent = "+ New category";
    select.appendChild(newOption);
    select.value = normalizeDeckCategory(currentCategory);

    const newField = shell.querySelector("[data-category-new-field]");
    const newInput = shell.querySelector("[data-category-new]");
    const cleanup = (value = null) => {
      modal.remove();
      resolve(value);
    };

    select.addEventListener("change", () => {
      newField.hidden = select.value !== "__new__";
      if (!newField.hidden) newInput.focus();
    });
    shell.querySelectorAll("[data-category-cancel]").forEach((button) => {
      button.addEventListener("click", () => cleanup(null));
    });
    shell.querySelector("[data-category-save]").addEventListener("click", () => {
      if (select.value === "__new__" && !newInput.value.trim()) {
        setStatus("Category cannot be empty.", "error");
        newInput.focus();
        return;
      }
      cleanup(normalizeDeckCategory(select.value === "__new__" ? newInput.value : select.value));
    });
    newInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        if (!newInput.value.trim()) {
          setStatus("Category cannot be empty.", "error");
          return;
        }
        cleanup(normalizeDeckCategory(newInput.value));
      }
      if (event.key === "Escape") cleanup(null);
    });
    modal.addEventListener("click", (event) => {
      if (event.target === modal) cleanup(null);
    });

    modal.appendChild(shell);
    document.body.appendChild(modal);
    select.focus();
  });
}

// Asks Cards vs Notes before a bulk export (Export All / multi-select) runs —
// unlike the single active-deck view, which already has separate Export and
// Export Notes buttons, a bulk export otherwise has no way to say which one
// you actually wanted. Resolves "cards" | "notes" | null (cancelled).
function chooseExportContent() {
  return new Promise((resolve) => {
    const modal = document.createElement("section");
    modal.className = "category-choice-modal";
    modal.setAttribute("aria-label", "Choose what to export");

    const shell = document.createElement("div");
    shell.className = "category-choice-shell";
    shell.innerHTML = `
      <div class="category-choice-head">
        <div>
          <h2>Export</h2>
          <p>What would you like to export?</p>
        </div>
        <button type="button" data-export-content-cancel aria-label="Close">&#215;</button>
      </div>
      <div class="export-content-choices">
        <button type="button" class="export-content-choice" data-export-content="cards">
          <span class="export-content-choice-icon">&#128209;</span>
          <span>Cards</span>
        </button>
        <button type="button" class="export-content-choice" data-export-content="notes">
          <span class="export-content-choice-icon">&#128221;</span>
          <span>Notes</span>
        </button>
      </div>
      <div class="category-choice-actions">
        <button type="button" data-export-content-cancel>Cancel</button>
      </div>
    `;

    const cleanup = (value = null) => {
      modal.remove();
      resolve(value);
    };
    shell.querySelectorAll("[data-export-content-cancel]").forEach((button) => {
      button.addEventListener("click", () => cleanup(null));
    });
    shell.querySelectorAll("[data-export-content]").forEach((button) => {
      button.addEventListener("click", () => cleanup(button.dataset.exportContent));
    });
    modal.addEventListener("click", (event) => {
      if (event.target === modal) cleanup(null);
    });

    modal.appendChild(shell);
    document.body.appendChild(modal);
    shell.querySelector(".export-content-choice")?.focus();
  });
}

// Whichever of two ISO timestamps (either may be null/undefined) is later,
// or null if neither parses.
function laterIsoTimestamp(a, b) {
  const ta = Date.parse(a || "");
  const tb = Date.parse(b || "");
  if (!Number.isFinite(ta)) return Number.isFinite(tb) ? b : null;
  if (!Number.isFinite(tb)) return a;
  return tb > ta ? b : a;
}

// Local counterpart of touchWebDeckAccess: bumps a deck's "last opened" time
// without touching updatedAt, so background reconcile reloads (which also call
// loadDeckFromLibrary) don't masquerade as a real visit — only the explicit
// open-from-My-Decks call sites invoke this.
function touchLocalDeckAccess(id) {
  if (!id) return;
  const index = readLocalDeckIndex();
  const entry = index.find((e) => e.id === id);
  if (!entry) return;
  entry.accessedAt = new Date().toISOString();
  writeLocalDeckIndex(index);
}

// A PostgREST UPDATE that matches NO rows is not an error — it is a successful
// request that changed nothing. Under RLS that is the normal shape of "this row
// isn't yours" and of "this row no longer exists", so these three writers
// reported success for both. `.select("id")` makes the server return what it
// actually touched, which is the only way to tell the difference. The decks.meta
// writers already do this; these did not.
async function updatedDeckRow(builder, label) {
  const { data, error } = await builder.select("id");
  if (error) throw error;
  if (!data || data.length === 0) {
    throw new Error(
      `Couldn't ${label} in the cloud — that deck isn't there, or it belongs to another account.`
    );
  }
  return true;
}

async function touchWebDeckAccess(deckId) {
  if (!deckId || !supabaseClient) return false;

  // The one exception: this is a background bookkeeping touch fired whenever a
  // deck is opened or exported. A deck that only exists locally has no cloud row
  // to touch, which is ordinary rather than a fault, so a zero-row result here
  // stays quiet — nothing downstream depends on it having landed.
  const { error } = await supabaseClient
    .from("decks")
    .update({
      last_accessed_at: new Date().toISOString()
    })
    .eq("id", deckId);

  if (error) throw error;
  return true;
}


async function updateWebDeckTitle(deckId, title) {
  if (!deckId || !supabaseClient) return false;

  const now = new Date().toISOString();
  await updatedDeckRow(
    supabaseClient.from("decks").update({ title, updated_at: now }).eq("id", deckId),
    "rename that deck"
  );
  await syncLocalLibraryMetaForDeck(deckId, { title, now });
  return true;
}

async function updateWebDeckCategory(deckId, category) {
  if (!deckId || !supabaseClient) return false;

  const normalized = normalizeDeckCategory(category);
  const now = new Date().toISOString();
  await updatedDeckRow(
    supabaseClient.from("decks").update({ category: normalized, updated_at: now }).eq("id", deckId),
    "move that deck"
  );
  await syncLocalLibraryMetaForDeck(deckId, { category: normalized, now });
  return true;
}

async function applyWebDeckCategory(deckId, category) {
  const normalized = normalizeDeckCategory(category);
  setKnownWebDeckCategories([...webDeckCategories, normalized]);
  await updateWebDeckCategory(deckId, normalized);

  if (state.deckId === deckId) {
    state.deckCategory = normalized;
    updateMeta();
  }

  return normalized;
}

function closeWebDeckExportMenus(exceptMenu = null) {
  document.querySelectorAll(".web-deck-export-menu, .bulk-export-menu").forEach((menu) => {
    if (menu !== exceptMenu) {
      menu.hidden = true;
      const trigger = menu.previousElementSibling;
      if (trigger?.matches("[aria-expanded]")) trigger.setAttribute("aria-expanded", "false");
    }
  });
}

function downloadTextFile(content, filename, type = "text/plain;charset=utf-8") {
  const blob = new Blob([content], { type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function normalizeWebDeckPayload(deckData, cardsData = []) {
  const deck = {
    id: String(deckData.id || ""),
    title: String(deckData.title || "Untitled"),
    category: normalizeDeckCategory(deckData.category),
    notes: String(deckData.notes || ""),
    meta: deckData.meta && typeof deckData.meta === "object" ? deckData.meta : {},
    current_card_index: Number(deckData.current_card_index) || 0,
    created_at: deckData.created_at || null,
    updated_at: deckData.updated_at || null,
    last_accessed_at: deckData.last_accessed_at || null
  };

  const cards = (cardsData || []).map((card, index) => ({
    id: String(card.id || `${deck.id}-${index}`),
    deck_id: String(card.deck_id || deck.id),
    question: String(card.question || ""),
    answer: String(card.answer || ""),
    position: Number.isFinite(Number(card.position)) ? Number(card.position) : index,
    status: normalizeCardStatus(card.status),
    // Free subject label for quick_notes cards; null on regular study cards.
    category: card.category ? String(card.category) : null,
    created_at: card.created_at || null,
    updated_at: card.updated_at || null
  }));

  return { deck, cards };
}

function deckPayloadSnapshot(payload) {
  return {
    app: "recall", // informational only — imports never read this field, so old "markdown-flashcards" exports still load
    version: 1,
    exportedAt: new Date().toISOString(),
    // The deck's REAL last-edited time (distinct from exportedAt, the moment the
    // archive was written). Restore compares this to decide newest-wins, so it
    // must survive the round-trip; falls back to null for older exports.
    updatedAt: payload.deck.updated_at || null,
    deckTitle: payload.deck.title,
    deckCategory: payload.deck.category,
    notes: payload.deck.notes || "",
    // Deck-level bag — carries the quick_notes managed category set through
    // backup/restore so restored notes still resolve their labels.
    meta: payload.deck.meta && typeof payload.deck.meta === "object" ? payload.deck.meta : {},
    sourceTitle: payload.deck.title,
    importTitleHint: payload.deck.title,
    deckId: payload.deck.id,
    current: payload.deck.current_card_index || 0,
    cards: payload.cards.map((card) => ({
      id: card.id,
      question: card.question,
      answer: card.answer,
      status: card.status,
      // Quick-note subject label carried through backup/restore + reconcile.
      category: card.category || null,
      // Per-card last-edited time when known, so card-level conflicts can also
      // resolve newest-wins instead of blindly overwriting a newer local edit.
      updatedAt: card.updated_at || null
    }))
  };
}

function statusByIdFromCards(cards = []) {
  return cards.reduce((statusById, card) => {
    const status = normalizeCardStatus(card.status);
    if (status) statusById[card.id] = status;
    return statusById;
  }, {});
}

// Quick-note subject label for a card: state.categoryById is authoritative
// while a deck is open (the board writes there), with the card's own field as
// the fallback for cards that never went through a deck load.
function quickNoteCategoryForCard(card) {
  if (!card || !card.id) return null;
  const assigned = state.categoryById[card.id];
  if (assigned) return String(assigned);
  return card.category ? String(card.category) : null;
}

// Apply a loaded deck's meta bag to the in-memory category set. Only the
// quick_notes deck owns this set: loading an ordinary deck must leave it alone,
// or its (empty) meta would blank the categories the board still needs. Falls
// back to the local cache so an offline/pre-migration load still has labels.
function applyDeckMetaCategories(meta, deckId, title) {
  if (!isQuickNotesDeck(deckId, title)) return;
  const fromMeta = quickNoteCategoriesFromMeta(meta);
  if (fromMeta.length) {
    state.quickNoteCategories = fromMeta;
    writeCachedQuickNoteCategories(fromMeta);
  } else {
    state.quickNoteCategories = readCachedQuickNoteCategories();
  }
}

async function fetchWebDeckPayload(deckId) {
  const { data: deckData, error: deckError } = await supabaseClient
    .from("decks")
    .select("*")
    .eq("id", deckId)
    .single();

  if (deckError) throw deckError;

  const { data: cardsData, error: cardsError } = await supabaseClient
    .from("cards")
    .select("*")
    .eq("deck_id", deckId)
    .order("position", { ascending: true });

  if (cardsError) throw cardsError;
  return normalizeWebDeckPayload(deckData, cardsData || []);
}

function webDeckPayloadMarkdown(payload) {
  const notesBlock = notesExportBlock(payload.deck.notes);
  return [
    `# ${payload.deck.title}`,
    "",
    `Category: ${payload.deck.category}`,
    `Deck ID: ${payload.deck.id}`,
    `Exported: ${new Date().toISOString()}`,
    "",
    formatCardList("Cards", payload.cards),
    notesBlock ? "" : null,
    notesBlock || null
  ].filter((line) => line !== null).join("\n");
}

function sqlValue(value) {
  if (value === null || value === undefined) return "NULL";
  return `'${String(value).replace(/'/g, "''")}'`;
}

function sqlTimestamp(value, fallback = new Date().toISOString()) {
  const parsed = value ? new Date(value) : null;
  return sqlValue(parsed && !Number.isNaN(parsed.getTime()) ? parsed.toISOString() : fallback);
}

// `includeNotes`/`includeCards` default true (today's full-deck export). A
// bulk "Cards" or "Notes" only export sets one of these false — critically,
// that must OMIT the notes column / the cards DELETE+INSERT entirely rather
// than sending a blanked value through the normal upsert, which would (if this
// script is ever run against a live database) silently wipe the omitted half
// of every deck it touches instead of just leaving it out of the file.
function buildDeckSql(payloads, title = "Recall SQL Export", { includeNotes = true, includeCards = true } = {}) {
  const lines = [
    `-- ${title}`,
    `-- Exported: ${new Date().toISOString()}`,
    "BEGIN;"
  ];

  payloads.forEach((payload) => {
    const deck = payload.deck;
    lines.push("");
    // Strip newlines before interpolating into a line comment — unlike the
    // INSERT below (escaped via sqlValue), a title containing a literal
    // newline here would break out of the "--" comment and let the rest of
    // the title be interpreted as SQL.
    lines.push(`-- Deck: ${String(deck.title || "").replace(/\r?\n/g, " ")}`);
    const notesColumns = includeNotes ? [["notes", sqlValue(deck.notes || "")]] : [];
    const columns = [
      ["id", sqlValue(deck.id)],
      ["title", sqlValue(deck.title)],
      ["category", sqlValue(deck.category)],
      ...notesColumns,
      // Carries the quick_notes deck's managed category set; without it a
      // restore from this file leaves every note's label pointing at a
      // category that no longer exists.
      ["meta", `${sqlValue(JSON.stringify(deck.meta || {}))}::jsonb`],
      ["current_card_index", Number(deck.current_card_index) || 0],
      ["created_at", sqlTimestamp(deck.created_at)],
      ["updated_at", sqlTimestamp(deck.updated_at)],
      ["last_accessed_at", sqlTimestamp(deck.last_accessed_at)]
    ];
    const updateColumns = ["title", "category", ...(includeNotes ? ["notes"] : []), "meta", "current_card_index", "updated_at", "last_accessed_at"];
    lines.push(
      `INSERT INTO decks (${columns.map(([name]) => name).join(", ")}) VALUES ` +
      `(${columns.map(([, value]) => value).join(", ")}) ` +
      "ON CONFLICT (id) DO UPDATE SET " +
      updateColumns.map((name) => `${name} = EXCLUDED.${name}`).join(", ") + ";"
    );

    if (includeCards) {
      lines.push(`DELETE FROM cards WHERE deck_id = ${sqlValue(deck.id)};`);
      if (payload.cards.length) {
        const values = payload.cards.map((card, index) => (
          `(${sqlValue(card.id)}, ${sqlValue(deck.id)}, ${sqlValue(card.question)}, ${sqlValue(card.answer)}, ${Number.isFinite(Number(card.position)) ? Number(card.position) : index}, ${sqlValue(normalizeCardStatus(card.status))}, ${sqlValue(card.category || null)}, ${sqlTimestamp(card.created_at)}, ${sqlTimestamp(card.updated_at)})`
        ));
        lines.push(
          "INSERT INTO cards (id, deck_id, question, answer, position, status, category, created_at, updated_at) VALUES\n" +
          values.join(",\n") +
          "\nON CONFLICT (id) DO UPDATE SET " +
          "deck_id = EXCLUDED.deck_id, question = EXCLUDED.question, answer = EXCLUDED.answer, position = EXCLUDED.position, status = EXCLUDED.status, category = EXCLUDED.category, updated_at = EXCLUDED.updated_at;"
        );
      }
    }
  });

  lines.push("");
  lines.push("COMMIT;");
  return `${lines.join("\n")}\n`;
}

function currentDeckPayload(scope = "all") {
  const deckTitle = state.deckTitle || state.sourceTitle || "Untitled Deck";
  const deckId = state.deckId || slugifyFileName(deckTitle);
  const cards = cardsForScope(scope).map((card, index) => ({
    id: card.id,
    deck_id: deckId,
    question: card.question,
    answer: card.answer,
    position: index,
    status: normalizeCardStatus(state.statusById[card.id]),
    category: quickNoteCategoryForCard(card),
    created_at: null,
    updated_at: new Date().toISOString()
  }));

  return {
    deck: {
      id: deckId,
      title: deckTitle,
      category: normalizeDeckCategory(state.deckCategory),
      notes: state.notes || "",
      meta: isQuickNotesDeck(deckId, deckTitle) && state.quickNoteCategories.length
        ? { quickNoteCategories: state.quickNoteCategories }
        : {},
      current_card_index: Number.isFinite(state.current) ? state.current : 0,
      created_at: null,
      updated_at: new Date().toISOString(),
      last_accessed_at: new Date().toISOString()
    },
    cards
  };
}

function exportSql(scope = "all") {
  const payload = currentDeckPayload(scope);
  if (!payload.cards.length) {
    setStatus("No cards to export as SQL.", "error");
    return;
  }

  downloadTextFile(
    buildDeckSql([payload], `${payload.deck.title} SQL Export`),
    `${exportBaseName(scope)}.sql`,
    "application/sql;charset=utf-8"
  );
  setStatus("Exported current deck as SQL.");
}

// Bumped by every deck-open attempt (web or local), so an in-flight one can
// tell whether it's still the load the user actually wants applied. A big
// note's web fetch can take long enough that the user opens a different deck
// from My Decks before it resolves — without this, the slower response lands
// LAST and silently overwrites whatever the user navigated to with the deck
// they left. See the checks in loadWebDeck and loadDeckFromLibrary below.
let activeDeckLoadToken = 0;

async function loadWebDeck(deckId) {
  if (!deckId || !supabaseClient) return;
  if (!navigator.onLine) {
    setStatus("Offline — can't load web decks. Try “My Decks” for device copies.", "error");
    showToast("Offline — can't load web deck", "info");
    return;
  }

  setStatus("Loading deck from web...");
  // A navigation door — see recordNavHistory. Recorded synchronously, before
  // the await below can let anything else move the user.
  recordNavHistory();
  const loadToken = ++activeDeckLoadToken;

  try {
    const [deckResult, cardsResult] = await Promise.all([
      withTimeout(abortable((signal) => supabaseClient.from("decks").select("*").eq("id", deckId).single().abortSignal(signal)), CLOUD_TIMEOUT_MS, "load deck"),
      withTimeout(abortable((signal) => supabaseClient.from("cards").select("*").eq("deck_id", deckId).order("position", { ascending: true }).abortSignal(signal)), CLOUD_TIMEOUT_MS, "load cards")
    ]);

    const { data: deckData, error: deckError } = deckResult;
    if (deckError) throw deckError;

    const { data: cardsData, error: cardsError } = cardsResult;
    if (cardsError) throw cardsError;

    // The user opened a different deck (local or web) while this fetch was in
    // flight — that newer load already owns the view. Applying this response
    // now would yank the screen back to the deck the user left.
    if (loadToken !== activeDeckLoadToken) return;
    // Flush the outgoing deck's debounced keystrokes while `state` still
    // describes it — see flushPendingDeckAutosave — then re-check the token,
    // because that flush is another await.
    await flushPendingDeckAutosave();
    if (loadToken !== activeDeckLoadToken) return;

    const statusById = {};
    const categoryById = {};
    const cards = cardsData.map((rawCard, index) => {
      const id = String(rawCard.id || `${index}-${rawCard.question.slice(0, 32)}`);
      const status = normalizeCardStatus(rawCard.status);
      if (status) {
        statusById[id] = status;
      }
      if (rawCard.category) categoryById[id] = String(rawCard.category);
      return { id, question: rawCard.question, answer: rawCard.answer };
    });

    state.deckId = deckData.id;
    state.masterCards = cards.slice();
    resetStudyDeck(state.masterCards);
    state.statusById = statusById;
    state.categoryById = categoryById;
    // Managed category set lives on the deck's meta bag (quick_notes only).
    applyDeckMetaCategories(deckData.meta, deckData.id, deckData.title);
    // Carry the whole meta bag forward (not just the quick_notes categories
    // pulled out above) so per-deck fields like a synced reading position
    // survive the next autosave instead of being silently dropped.
    state.meta = deckData.meta && typeof deckData.meta === "object" ? deckData.meta : {};
    state.current = 0; // always start from the first card on fresh load
    state.deckTitle = deckData.title || "";
    state.deckCategory = normalizeDeckCategory(deckData.category);
    // MUST come before state.notes is replaced — the loadDeckSnapshot sibling
    // of this line explains why an open raw editor outlives a deck swap and
    // what it overwrites when it does.
    discardNotesEditingForDeckSwap();
    // The deck being left is the last thing that needed its queued images'
    // blob URLs. See revokeLocalImageUrls for why the session can't wait for
    // pagehide to release them.
    revokeLocalImageUrls();
    // Pre-migration databases have no notes column; select("*") just omits it.
    state.notes = String(deckData.notes || "");
    state.sourceTitle = deckData.title || "";
    state.importTitleHint = deckData.title || "";
    setViewMode("notes");
    // Cross-device resume: this deck's meta may carry a reading position
    // synced from another device. Ambient landing, not a deliberate jump —
    // no flash, no animated scroll. scheduleNoteJump no-ops quietly if the
    // anchor can't be found (notes changed since, or this is the first time
    // this deck has ever had a position saved).
    if (state.meta?.readingPosition) scheduleNoteJump(state.meta.readingPosition, { flash: false, smooth: false });

    syncResults();
    touchWebDeckAccess(deckData.id).catch((error) => console.error("Failed to touch deck access", error));
    closeAllCardsPanel();
    setStatus(`Loaded ${cards.length} cards from web successfully.`);
    showToast(`Loaded "${state.deckTitle || "deck"}" · ${cards.length} cards`);
    if (el.myDecksPanel) el.myDecksPanel.hidden = true;
    unlockPageScroll();
    closeImportPanel();
    showCard();
    // Mirror the freshly-loaded web deck into the on-device library (deduped by
    // cloud id) so it stays readable offline without an extra manual save. Align
    // its timestamps to the cloud copy so it reads as already in-sync — otherwise
    // it would look "newer" and trigger a redundant re-push on the next reconcile.
    // Skipped entirely once superseded: saveDeckToLibrary assigns state.localDeckId
    // as a side effect, and running that for a deck the user has since navigated
    // away from would yank state.localDeckId back to it out from under whatever
    // deck is actually on screen now.
    if (loadToken === activeDeckLoadToken) {
      state.localDeckId = null;
      const mirroredMeta = await saveDeckToLibrary({ silent: true, updatedAt: deckData.updated_at, lastSyncedAt: deckData.updated_at, synced: true });
      if (loadToken === activeDeckLoadToken) {
        if (mirroredMeta) touchLocalDeckAccess(mirroredMeta.id);
        refreshSyncIndicatorBaseline();
        refreshNavBack(); // arrived — now the button knows where "here" is
        resetChromeAutoHide(); // a new deck starts at the top, header showing
      }
    }
  } catch (error) {
    setStatus("Failed to load deck from web.", "error");
    showToast("Couldn't load deck", "error");
    console.error(error);
  }
}

function normalizeSyncText(value) {
  return normalizeMarkdown(String(value || ""))
    .replace(/[ \t]+$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function syncTextChanged(localValue, webValue) {
  return normalizeSyncText(localValue) !== normalizeSyncText(webValue);
}

function sameSyncContent(localCard, webCard) {
  return !syncTextChanged(localCard.question, webCard.question)
    && !syncTextChanged(localCard.answer, webCard.answer);
}

function uniqueMatchingWebCard(webCards, predicate) {
  const matches = webCards.filter(predicate);
  return matches.length === 1 ? matches[0] : null;
}

function fallbackWebCardFor(localCard, localIndex, unmatchedWebCards, localIds) {
  const candidates = unmatchedWebCards.filter((webCard) => !localIds.has(String(webCard.id)));

  return uniqueMatchingWebCard(candidates, (webCard) => sameSyncContent(localCard, webCard))
    || uniqueMatchingWebCard(candidates, (webCard) => Number(webCard.position) === localIndex)
    || uniqueMatchingWebCard(candidates, (webCard) => (
      normalizeSyncText(localCard.question)
      && normalizeSyncText(localCard.question) === normalizeSyncText(webCard.question)
    ))
    || uniqueMatchingWebCard(candidates, (webCard) => (
      normalizeSyncText(localCard.answer)
      && normalizeSyncText(localCard.answer) === normalizeSyncText(webCard.answer)
    ));
}

// `fuzzy` (default on) lets a local card with no exact id match pair up with a
// web card by content/position — right when the two sides may have drifted ids
// (e.g. an import-minted local deck vs its first web copy). It is WRONG for a
// stable-id diff (old library snapshot vs the same deck's cloud rows), where a
// genuinely deleted card would get spuriously paired with a genuinely added one
// and both miscounted as an "update" — pass `{ fuzzy: false }` there.
function calculateSyncDiff(localCards, webCards, statusById = {}, { fuzzy = true } = {}) {
  const unmatchedWeb = new Map(webCards.map((card) => [String(card.id), card]));
  const localIds = new Set(localCards.map((card) => String(card.id)));
  const changes = {
    added: 0,
    deleted: 0,
    edited: 0,
    moved: 0,
    statusChanges: 0,
    categoryChanges: 0
  };

  localCards.forEach((localCard, index) => {
    const id = String(localCard.id);
    let webCard = unmatchedWeb.get(id) || null;

    if (!webCard && fuzzy) {
      webCard = fallbackWebCardFor(localCard, index, Array.from(unmatchedWeb.values()), localIds);
    }

    if (!webCard) {
      changes.added += 1;
      return;
    }

    unmatchedWeb.delete(String(webCard.id));

    if (syncTextChanged(localCard.question, webCard.question) || syncTextChanged(localCard.answer, webCard.answer)) {
      changes.edited += 1;
    }

    const webPosition = Number(webCard.position);
    if (Number.isFinite(webPosition) && webPosition !== index) {
      changes.moved += 1;
    }

    const localStatus = normalizeCardStatus(statusById[id]);
    const webStatus = normalizeCardStatus(webCard.status);
    if (localStatus !== webStatus) {
      changes.statusChanges += 1;
    }

    // Quick-note label moves are real changes; without this a pull that only
    // recategorised notes reported "no per-card changes".
    if ((localCard.category || null) !== (webCard.category || null)) {
      changes.categoryChanges += 1;
    }
  });

  changes.deleted = unmatchedWeb.size;
  return changes;
}

// ── Per-card sync bookkeeping ───────────────────────────────────────────────
// Deck-level last-write-wins used to be the whole conflict story: a pull
// replaced the local snapshot wholesale, so every card this device had changed
// while offline was destroyed — silently, unrecoverably — the moment another
// device touched the same deck afterwards. Two device-local fields on each
// snapshot card are what let the pull MERGE instead of overwrite:
//
//   dirty     — changed here and not yet confirmed present in the cloud
//   updatedAt — when this device last changed it
//
// Together they encode the sync base without storing a second full snapshot per
// deck (localStorage is already the binding constraint here — see
// isQuotaExceededError / deckAutosaveStorageFailed). Neither field is ever sent
// to the cloud; they describe this device's relationship to it.
//
// Snapshots written by older builds carry neither: a missing `dirty` reads as
// false and a missing `updatedAt` falls back to the deck's own timestamp, which
// reduces the merge to exactly the old take-the-cloud behaviour for decks that
// predate this change.

// ── Per-card delete tombstones ──────────────────────────────────────────────
// `dirty` alone cannot express "I deleted this card": a deleted card leaves no
// object behind to carry a flag. That gap is what let deletions un-happen. The
// push is authoritative (pushDeckRowsToCloud prunes every cloud card missing
// from the snapshot it sends), and the direction is chosen per deck purely by
// timestamp — so a device holding a stale copy of a deck it has ALSO edited
// takes the push branch, never pulls, and re-upserts the card another device
// deleted. The card then comes back on every device on their next pull.
//
// So each snapshot carries `deletedCardIds` — { cardId: iso } — the ids this
// device deleted. Two rules use it:
//   push : a cloud card absent locally is pruned only if it is tombstoned here.
//          Otherwise it was ADDED on another device, and pruning it would be
//          the same bug pointing the other way.
//   pull : a cloud row that is tombstoned here is not re-adopted; the deck is
//          marked as owing a push so the deletion is re-asserted in the cloud.
// A tombstone is retired as soon as the cloud is observed not to have that id —
// the deletion has propagated and nothing can resurrect it (a device still
// holding the card clean drops it under the clean-and-absent rule). The age cap
// is only a backstop for a device that never syncs again.
const CARD_TOMBSTONE_MAX_AGE_MS = 180 * 24 * 60 * 60 * 1000;
const CARD_TOMBSTONE_MAX = 2000;

// Always a fresh plain object, so callers can mutate it without touching the
// snapshot they read it from.
function readCardTombstones(snapshot) {
  const raw = snapshot?.deletedCardIds;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const out = {};
  for (const [id, iso] of Object.entries(raw)) {
    if (id) out[String(id)] = typeof iso === "string" ? iso : new Date(0).toISOString();
  }
  return out;
}

// Age + count cap, so a deck that is edited for years can't grow an unbounded
// tombstone map inside a snapshot that has to fit in localStorage. Oldest go
// first when over the count cap.
function pruneCardTombstones(map) {
  const cutoff = Date.now() - CARD_TOMBSTONE_MAX_AGE_MS;
  let entries = Object.entries(map).filter(([, iso]) => tsMs(iso) >= cutoff);
  if (entries.length > CARD_TOMBSTONE_MAX) {
    entries.sort((a, b) => tsMs(b[1]) - tsMs(a[1]));
    entries = entries.slice(0, CARD_TOMBSTONE_MAX);
  }
  return Object.fromEntries(entries);
}

// The invariant every writer has to keep: a card that is PRESENT is not
// deleted. Snapshot paths that add cards by hand (a restore, a quick note
// pinned into another deck) must call this, or a re-created id would keep a
// tombstone that quietly blocks it from ever syncing again.
function dropTombstonesForLiveCards(snapshot) {
  const map = readCardTombstones(snapshot);
  if (!Object.keys(map).length) return snapshot;
  for (const card of snapshot.cards || []) delete map[String(card.id)];
  if (Object.keys(map).length) snapshot.deletedCardIds = map;
  else delete snapshot.deletedCardIds;
  return snapshot;
}

// Carries a deck's tombstones across a save: ids that were in the copy being
// replaced but aren't in the new one were just deleted here; ids that are back
// (an undo, or a re-import of the same card id) retire their tombstone, because
// the user's most recent action is the one that counts.
function recordDeletedCardIds(snapshot, previousSnapshot, stampIso) {
  const map = readCardTombstones(previousSnapshot);
  const liveIds = new Set((snapshot.cards || []).map((card) => String(card.id)));
  for (const card of previousSnapshot?.cards || []) {
    const id = String(card.id || "");
    if (id && !liveIds.has(id)) map[id] = stampIso;
  }
  const pruned = pruneCardTombstones(map);
  snapshot.deletedCardIds = pruned;
  return dropTombstonesForLiveCards(snapshot);
}

// The fields that make a card materially different — i.e. the ones worth
// pushing. Deliberately excludes position (tracked by the deck's card order)
// and noteAnchor (device-local; the cards table has no column for it).
function cardSyncSignature(card) {
  return [
    normalizeSyncText(card?.question),
    normalizeSyncText(card?.answer),
    normalizeCardStatus(card?.status),
    card?.category || ""
  ].join("␟");
}

function cardIsDirty(card) {
  return Boolean(card && card.dirty);
}

// A card's local edit time, falling back to the deck's timestamp for snapshots
// written before per-card stamps existed.
function cardUpdatedMs(card, fallbackIso) {
  return tsMs(card?.updatedAt || fallbackIso);
}

// Stamps dirty/updatedAt onto a freshly built snapshot by diffing it against the
// copy it is about to replace. Called from saveDeckToLibrary — the one choke
// point every local deck edit passes through. A card whose content is unchanged
// keeps its previous flags, so a card still waiting to be pushed stays dirty
// across any number of unrelated saves. `synced` is for the one case where the
// snapshot is known to match the cloud already (mirroring a just-loaded web
// deck): everything is clean, and nothing gets re-pushed for no reason.
function stampCardSyncState(snapshot, previousSnapshot, stampIso, { synced = false } = {}) {
  const previousById = new Map(
    (previousSnapshot?.cards || []).map((card) => [String(card.id), card])
  );
  for (const card of snapshot.cards || []) {
    if (synced) {
      card.dirty = false;
      card.updatedAt = stampIso;
      continue;
    }
    const previous = previousById.get(String(card.id));
    if (previous && cardSyncSignature(previous) === cardSyncSignature(card)) {
      card.dirty = cardIsDirty(previous);
      card.updatedAt = previous.updatedAt || stampIso;
    } else {
      card.dirty = true;
      card.updatedAt = stampIso;
    }
  }
  return snapshot;
}

// Merge one deck's incoming cloud rows into the copy this device already holds,
// card by card, instead of replacing the list:
//
//   local only, dirty         → keep   (added here, never pushed)
//   local only, clean         → drop   (it reached the cloud once, so the cloud
//                                       no longer having it IS a deletion)
//   in both, local dirty AND
//     strictly newer          → keep local
//   in both, otherwise        → take cloud (and it is clean from now on)
//   cloud only                → add
//
// Result order follows the cloud's row order (already sorted by `position`),
// with kept local-only cards appended in their existing relative order — they
// have no cloud position to slot into yet. `keptLocal` is what tells the caller
// this deck still owes the cloud a push after the pull, and so is
// `blockedResurrections` — a cloud row this device has tombstoned is skipped
// here and has to be re-deleted in the cloud by the following push.
function mergeCloudCardsIntoSnapshot(oldSnapshot, cloudCards, deckFallbackIso) {
  const localCards = Array.isArray(oldSnapshot?.cards) ? oldSnapshot.cards : [];
  const localById = new Map(localCards.map((card) => [String(card.id), card]));
  const tombstones = readCardTombstones(oldSnapshot);
  const merged = [];
  const seenLocalIds = new Set();
  const cloudIds = new Set();
  let keptLocal = 0;
  let blockedResurrections = 0;

  for (const row of cloudCards || []) {
    const id = String(row.id || "");
    if (!id) continue;
    cloudIds.add(id);
    // Deleted here, still in the cloud — another device re-pushed it, or our own
    // delete hasn't been pushed yet. Either way, adopting it back is exactly the
    // resurrection this tombstone exists to stop.
    if (tombstones[id]) {
      blockedResurrections += 1;
      continue;
    }
    const local = localById.get(id);
    const fromCloud = {
      id,
      question: row.question,
      answer: row.answer,
      status: normalizeCardStatus(row.status),
      category: row.category ? String(row.category) : null,
      dirty: false,
      updatedAt: row.updated_at || deckFallbackIso
    };
    if (local) {
      seenLocalIds.add(id);
      if (cardIsDirty(local) && cardUpdatedMs(local, deckFallbackIso) > tsMs(row.updated_at || deckFallbackIso)) {
        keptLocal += 1;
        merged.push({ ...local, id });
        continue;
      }
      // noteAnchor is a device-local link (the cloud `cards` table has no column
      // for it), so an incoming row never carries one. Re-attach what this
      // device already had, or every pull permanently breaks the quick-note
      // "jump to where this was pinned" button.
      if (local.noteAnchor) fromCloud.noteAnchor = local.noteAnchor;
    }
    merged.push(fromCloud);
  }

  // Zero cloud rows for a deck that has cards here is NOT read as "every card
  // was deleted elsewhere". It is what an unauthenticated read looks like (RLS
  // returns an empty set, not an error), and what a dropped page looks like —
  // and the cost of believing it is the entire deck, here and then in the cloud
  // on the next push. A deck genuinely emptied on another device still converges:
  // that device holds per-card tombstones and re-deletes these rows, which is
  // the evidence-based path. This only refuses the guess.
  const cloudLooksBlank = !(cloudCards || []).length && localCards.length > 0;

  for (const card of localCards) {
    const id = String(card.id || "");
    if (!id || seenLocalIds.has(id)) continue;
    // Clean and cloud-less means it was synced once and deleted elsewhere —
    // dropping it is the whole point of a two-way mirror. Only unpushed work
    // survives a cloud that has never heard of it.
    if (!cardIsDirty(card) && !cloudLooksBlank) continue;
    keptLocal += 1;
    merged.push({ ...card, id });
  }
  if (cloudLooksBlank) {
    console.warn(`Cloud returned 0 cards for a deck holding ${localCards.length} — keeping them all rather than treating it as a deletion.`);
  }

  // Retire the tombstones the cloud has already honoured. Keeping them past
  // that point would block a card the user later re-creates with the same id
  // (a restore from backup, say) from ever syncing again.
  const deletedCardIds = pruneCardTombstones(
    Object.fromEntries(Object.entries(tombstones).filter(([id]) => cloudIds.has(id)))
  );

  return { cards: merged, keptLocal, blockedResurrections, deletedCardIds };
}

// The push side of the same story. `pushLibraryDeckToCloud` sends the local card
// list and pushDeckRowsToCloud deletes every cloud row missing from it — which is
// only correct if the local list is a superset of "what the cloud has, minus what
// I deleted". This makes it one, using the deck's cloud rows (already fetched for
// the push diff) as the reference:
//
//   local, in cloud            → push
//   local only, dirty          → push   (added/edited here, cloud hasn't seen it)
//   local only, clean          → DROP   (it reached the cloud once and is gone
//                                        from it now — deleted on another device)
//   cloud only, tombstoned here → omit  (deleted here; the push prunes it)
//   cloud only, not tombstoned  → adopt (added on another device since our last
//                                        pull; pushing without it would delete
//                                        someone else's new card)
//
// Adopted rows are appended rather than slotted in at their cloud position: the
// push restamps positions from array order anyway, and appending keeps this
// device's own ordering intact.
function reconcileCardsBeforePush(snapshot, cloudCards) {
  const localCards = Array.isArray(snapshot?.cards) ? snapshot.cards : [];
  const tombstones = readCardTombstones(snapshot);
  const cloudById = new Map((cloudCards || []).map((row) => [String(row.id), row]));
  const localIds = new Set(localCards.map((card) => String(card.id)));

  // Dropping a clean local-only card only means "deleted elsewhere" if this
  // snapshot actually carries per-card sync state. A snapshot written by a build
  // that predates it has no `dirty` anywhere, so every card would read as clean
  // and a legitimately-unpushed card would be destroyed instead of uploaded.
  // Keep everything in that case; the push itself writes the fields back, so a
  // deck is legacy for exactly one sync.
  const hasCardSyncState = localCards.some((card) => card.dirty !== undefined || card.updatedAt);

  // The same refusal as the pull side (see mergeCloudCardsIntoSnapshot): a deck
  // whose cloud rows all came back empty is far more likely to be a bad read
  // than a deck someone emptied card by card — and here the stakes are higher
  // still, because these cards are about to be dropped from the snapshot AND
  // the push that follows prunes whatever it doesn't send. Believing a blank
  // read at this point deletes the deck's contents on every device at once.
  const cloudLooksBlank = !(cloudCards || []).length && localCards.length > 0;

  const cards = [];
  let dropped = 0;
  for (const card of localCards) {
    const id = String(card.id || "");
    if (!id) continue;
    if (hasCardSyncState && !cloudLooksBlank && !cloudById.has(id) && !cardIsDirty(card)) {
      dropped += 1;
      continue;
    }
    cards.push(card);
  }
  if (cloudLooksBlank) {
    console.warn(`Push diff saw 0 cloud cards for a deck holding ${localCards.length} — sending them all rather than pruning.`);
  }

  let adopted = 0;
  for (const row of cloudCards || []) {
    const id = String(row.id || "");
    if (!id || localIds.has(id) || tombstones[id]) continue;
    adopted += 1;
    cards.push({
      id,
      question: row.question,
      answer: row.answer,
      status: normalizeCardStatus(row.status),
      category: row.category ? String(row.category) : null,
      dirty: false,
      updatedAt: row.updated_at || new Date().toISOString()
    });
  }

  // Same retirement rule as the pull: a tombstone whose card is no longer in the
  // cloud has done its job.
  const deletedCardIds = pruneCardTombstones(
    Object.fromEntries(Object.entries(tombstones).filter(([id]) => cloudById.has(id)))
  );

  return { cards, dropped, adopted, deletedCardIds };
}

// Shared HTML for a sync report — every deck reconcileAllDecks() touched,
// what direction it went, and exactly what changed (cards added/updated/
// deleted, notes). Used both by the explicit-sync modal and the inline
// startup report on the welcome screen.
function buildSyncReportHtml(deckLog, { pulled = 0, pushed = 0, failed = 0 } = {}) {
  const describeCounts = (entry) => {
    const parts = describeSyncStats(entry);
    return parts.length ? parts.join(", ") : "no per-card changes (deck metadata only)";
  };

  const rows = deckLog.map((entry) => {
    if (entry.direction === "failed") {
      return `<li class="sync-report-row sync-report-row-error">
        <strong>${escapeHtml(entry.title)}</strong> — sync failed
        <div class="sync-report-detail">${escapeHtml(entry.error || "Unknown error")}</div>
      </li>`;
    }
    const dirLabel = entry.direction === "pulled"
      ? "⬇ Downloaded from cloud"
      : entry.direction === "removed"
        ? "🗑 Removed from this device"
        : "⬆ Uploaded to cloud";
    // A replaced notes body is the one thing sync can still overwrite, so it
    // gets an actual way out rather than only a line of prose saying it happened.
    const recover = entry.notesConflicted && entry.localId
      ? `<button type="button" class="sync-report-recover" data-recover-notes="${escapeHtml(entry.localId)}">Restore my notes</button>`
      : "";
    return `<li class="sync-report-row">
      <strong>${escapeHtml(entry.title)}</strong> — ${dirLabel}
      <div class="sync-report-detail">${describeCounts(entry)}</div>
      ${recover}
    </li>`;
  }).join("");

  return `
    <p class="sync-report-summary">${pulled} deck${pulled === 1 ? "" : "s"} downloaded, ${pushed} deck${pushed === 1 ? "" : "s"} uploaded${failed ? `, ${failed} failed` : ""}</p>
    <ul class="sync-report-list">${rows}</ul>
  `;
}

// Put back the deck-notes body a pull replaced. The stash holds the copy this
// device had; restoring appends it below the incoming text under a marker
// rather than replacing it, so neither version is lost and the user can edit
// the two together. Bumps updatedAt so the merged result is what gets pushed.
async function restoreStashedNotes(localId) {
  const stash = await readDeckSnapshot(localId + NOTES_CONFLICT_SUFFIX);
  if (!stash || !String(stash.notes || "").trim()) {
    // Nothing to put back, so there is no longer a conflict to answer. Without
    // this the flag outlived the stash and the deck advertised a conflict whose
    // resolver could only ever say "nothing left to restore" — a dead end that
    // no amount of syncing cleared.
    clearNotesConflictFlag(localId);
    await refreshAfterNotesConflictResolved(localId, { reload: false });
    showToast("Nothing left to restore", "info");
    return false;
  }

  const snapshot = await readDeckSnapshot(localId);
  if (!snapshot) {
    showToast("That deck is no longer on this device", "error");
    return false;
  }

  const when = stash.savedAt ? new Date(stash.savedAt).toLocaleString() : "an earlier sync";
  const marker = `\n\n---\n\n## Your notes from before ${when}\n\n${stash.notes}\n`;
  snapshot.notes = String(snapshot.notes || "") + marker;
  const now = new Date().toISOString();
  writeDeckSnapshot(localId, snapshot);
  const index = readLocalDeckIndex();
  const entry = index.find((m) => m.id === localId);
  if (entry) {
    entry.updatedAt = now;
    entry.hasNotes = true;
    // The conflict is resolved — both versions are now in the notes body, and
    // the stash below is about to be deleted. Without clearing this the deck
    // would keep showing "Notes conflict" forever, pointing at a stash that no
    // longer exists.
    entry.notesConflicted = false;
    writeLocalDeckIndex(index);
  }
  deleteDeckSnapshot(localId + NOTES_CONFLICT_SUFFIX);
  await refreshAfterNotesConflictResolved(localId);
  showToast("Your notes were added back at the end of the deck's notes", "success");
  return true;
}

// ── Notes conflicts: reaching, and answering, one ──────────────────────────
// A conflict is a purely local condition — a stashed copy of the notes this
// device lost, sitting beside the deck under NOTES_CONFLICT_SUFFIX. The status
// pills (deckSyncStatus, setSyncIndicator) report it, and both now open the
// resolver below.
//
// They previously did not, and there was no other way in: the only "Restore my
// notes" button lived inside the post-sync report, which is built from the log
// of ONE reconcile. Running "Sync Now" again — exactly what the pill told the
// reader to do — found the deck already matching, logged nothing, and rendered
// no report at all, while a background sync's report only ever painted on the
// welcome screen and was gone on reload. So the pill said "notes conflict" and
// offered nothing, permanently. The stash was intact the whole time; it just
// had no door.

function notesConflictStashKey(localId) {
  return localId + NOTES_CONFLICT_SUFFIX;
}

// Clears the persisted flag. Deliberately does NOT touch the stash — callers
// decide whether the losing copy is still wanted.
function clearNotesConflictFlag(localId, { touch = false } = {}) {
  const index = readLocalDeckIndex();
  const entry = index.find((m) => m.id === localId);
  if (!entry) return false;
  entry.notesConflicted = false;
  // Only when the resolution CHANGED the notes: a bumped updatedAt is what makes
  // the next push carry the result up. Accepting the synced copy changes nothing
  // locally and must not fake an edit.
  if (touch) entry.updatedAt = new Date().toISOString();
  writeLocalDeckIndex(index);
  return true;
}

async function refreshAfterNotesConflictResolved(localId, { reload = true } = {}) {
  if (reload && state.localDeckId === localId) await loadDeckFromLibrary(localId);
  if (el.myDecksPanel && !el.myDecksPanel.hidden) renderMyDecksList();
  refreshSyncIndicatorBaseline();
}

// "both" is restoreStashedNotes (append under a dated marker, nothing lost).
// "mine" promotes the stashed copy to BE the notes. "synced" accepts what
// arrived and drops the stash. All three clear the flag, because a conflict the
// reader has answered must stop advertising itself — the flag used to be sticky
// until the deck happened to be pulled again (only a pull recomputes it, and a
// push never clears it), so a deck that was never pulled again showed "Notes
// conflict" for good.
async function resolveNotesConflict(localId, choice) {
  if (choice === "both") return restoreStashedNotes(localId);

  const snapshot = await readDeckSnapshot(localId);
  if (!snapshot) {
    showToast("That deck is no longer on this device", "error");
    return false;
  }

  if (choice === "mine") {
    const stash = await readDeckSnapshot(notesConflictStashKey(localId));
    if (!stash || !String(stash.notes || "").trim()) {
      clearNotesConflictFlag(localId);
      await refreshAfterNotesConflictResolved(localId, { reload: false });
      showToast("Nothing left to restore", "info");
      return false;
    }
    snapshot.notes = String(stash.notes || "");
    writeDeckSnapshot(localId, snapshot);
    const index = readLocalDeckIndex();
    const entry = index.find((m) => m.id === localId);
    if (entry) entry.hasNotes = Boolean(snapshot.notes.trim());
    writeLocalDeckIndex(index);
    clearNotesConflictFlag(localId, { touch: true });
  } else {
    clearNotesConflictFlag(localId);
  }

  deleteDeckSnapshot(notesConflictStashKey(localId));
  await refreshAfterNotesConflictResolved(localId, { reload: choice === "mine" });
  showToast(
    choice === "mine"
      ? "Your version is back — it will upload on the next sync"
      : "Kept the synced version; your saved copy was discarded",
    "success"
  );
  return true;
}

// Enough of each version to tell them apart at a glance. Plain text, not
// rendered markdown: the point is to identify a version, and a 300KB note
// rendered into a modal would be neither quick nor readable.
const NOTES_CONFLICT_PREVIEW_CHARS = 600;
function notesConflictPreview(text) {
  const body = String(text || "").trim();
  if (!body) return `<p class="notes-conflict-empty">(empty)</p>`;
  const clipped = body.slice(0, NOTES_CONFLICT_PREVIEW_CHARS);
  const more = body.length > clipped.length ? "\n…" : "";
  return `<pre class="notes-conflict-preview">${escapeHtml(clipped + more)}</pre>`;
}

// The resolver itself. Reuses the #syncModal chrome the same way showSyncReport
// does — its footer Cancel becomes "Close", and the three real choices are
// buttons in the body so they can carry their own explanation.
async function showNotesConflictModal(localId) {
  const modal = el.syncModal;
  const content = el.syncDetailsContent;
  if (!modal || !content || !localId) return;

  const [snapshot, stash] = await Promise.all([
    readDeckSnapshot(localId),
    readDeckSnapshot(notesConflictStashKey(localId))
  ]);

  if (!stash || !String(stash.notes || "").trim()) {
    clearNotesConflictFlag(localId);
    await refreshAfterNotesConflictResolved(localId, { reload: false });
    showToast("That conflict has already been dealt with", "info");
    return;
  }

  const titleEl = document.getElementById("syncModalTitle");
  const confirmBtn = document.getElementById("confirmSyncBtn");
  const cancelBtn = document.getElementById("cancelSyncBtn");
  if (titleEl) titleEl.textContent = "Notes conflict";
  if (confirmBtn) confirmBtn.hidden = true;
  if (cancelBtn) cancelBtn.textContent = "Decide later";

  const when = stash.savedAt ? new Date(stash.savedAt).toLocaleString() : "an earlier sync";
  const deckTitle = snapshot?.deckTitle || stash.deckTitle || "this deck";

  content.innerHTML = `
    <p class="notes-conflict-intro">
      Another device saved a newer version of <strong>${escapeHtml(deckTitle)}</strong>'s notes, and
      syncing replaced the copy on this device. Your copy was saved on ${escapeHtml(when)} and is still
      here — choose which one to keep.
    </p>
    <div class="notes-conflict-versions">
      <section class="notes-conflict-version">
        <h3>Now on this device (from the other device)</h3>
        ${notesConflictPreview(snapshot?.notes)}
      </section>
      <section class="notes-conflict-version">
        <h3>Your saved copy</h3>
        ${notesConflictPreview(stash.notes)}
      </section>
    </div>
    <div class="notes-conflict-choices">
      <button type="button" class="sync-modal-btn is-primary" data-conflict-choice="both">
        Keep both
        <span>Adds your copy to the end, under a dated heading. Nothing is lost.</span>
      </button>
      <button type="button" class="sync-modal-btn" data-conflict-choice="mine">
        Keep mine
        <span>Replaces the notes with your copy and uploads it on the next sync.</span>
      </button>
      <button type="button" class="sync-modal-btn" data-conflict-choice="synced">
        Keep the synced version
        <span>Discards your saved copy. This cannot be undone.</span>
      </button>
    </div>
  `;

  content.onclick = async (event) => {
    const button = event.target.closest("[data-conflict-choice]");
    if (!button) return;
    const choice = button.dataset.conflictChoice;
    // Both destructive answers are one tap from here, so the irreversible one
    // asks first. "Keep both" and "Keep mine" leave every version recoverable.
    // Disabled rather than put through setButtonLoading: these buttons carry a
    // <span> of explanation, and that helper swaps textContent, which would
    // flatten the span away and never bring it back.
    const choices = Array.from(content.querySelectorAll("[data-conflict-choice]"));
    const run = async () => {
      choices.forEach((node) => { node.disabled = true; });
      try {
        if (await resolveNotesConflict(localId, choice)) modal.hidden = true;
      } finally {
        choices.forEach((node) => { node.disabled = false; });
      }
    };
    if (choice === "synced") {
      showConfirmModal(
        "Discard your saved copy of these notes and keep the synced version? This cannot be undone.",
        run,
        { confirmLabel: "Discard my copy", danger: true }
      );
      return;
    }
    await run();
  };

  modal.hidden = false;
}

// Post-sync report modal for an EXPLICIT "Sync Now" click only — background
// startup/reconnect syncs render their report inline on the welcome screen
// instead (see renderWelcomeSyncReport) rather than popping a modal.
// Reuses the (otherwise-dead, since the manual "Sync to Cloud" button it was
// written for no longer exists) #syncModal chrome, repurposed as a plain
// report instead of a confirm-before-you-sync prompt.
function showSyncReport(deckLog, { pulled = 0, pushed = 0, failed = 0 } = {}) {
  const modal = el.syncModal;
  const content = el.syncDetailsContent;
  if (!modal || !content) return;

  const titleEl = document.getElementById("syncModalTitle");
  const confirmBtn = document.getElementById("confirmSyncBtn");
  const cancelBtn = document.getElementById("cancelSyncBtn");
  if (titleEl) titleEl.textContent = "Sync Report";
  if (confirmBtn) confirmBtn.hidden = true;
  if (cancelBtn) cancelBtn.textContent = "Close";

  content.innerHTML = buildSyncReportHtml(deckLog, { pulled, pushed, failed });
  // Delegated so the buttons keep working across re-renders of the report.
  content.onclick = async (event) => {
    const button = event.target.closest("[data-recover-notes]");
    if (!button) return;
    if (await restoreStashedNotes(button.dataset.recoverNotes)) button.remove();
  };
  modal.hidden = false;
}

// How long any single cloud read/write is allowed to hang before we give up.
// A Supabase call over a dropped/stalled connection otherwise never settles,
// wedging sync (reconcileInFlight never resets) or an EPUB import (whose
// Cancel only polls between steps, not during a hung await).
const CLOUD_TIMEOUT_MS = 20000;

// Where withTimeout looks for the AbortController belonging to a request (see
// abortable() below).
const CLOUD_ABORT = Symbol("cloudAbort");

// Reject a hangable network promise after `ms` so a stalled connection fails
// cleanly instead of hanging forever. The message carries "load failed" so it
// classifies as offline through the existing detection regex (see the reconcile
// catch) and the user sees "Couldn't reach the cloud" rather than a spinner
// that never stops. The underlying request may still complete server-side; we
// only wrap idempotent upserts/reads/uploads, so a late success is harmless.
function withTimeout(promise, ms = CLOUD_TIMEOUT_MS, label = "") {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => {
      // supabase-js query builders are thenable and expose .abortSignal(), but
      // by the time we get here the request is already in flight — so cancel it
      // through the AbortController the caller attached, if any. Racing a timer
      // alone left the connection open and consuming one of the browser's very
      // few per-host sockets, which on a flaky mobile link is what turned one
      // stalled request into a whole sync crawling behind it.
      try { promise?.[CLOUD_ABORT]?.abort(); } catch (_) { /* already settled */ }
      reject(new Error(`Load failed — request timed out${label ? ` (${label})` : ""}`));
    }, ms);
  });
  return Promise.race([Promise.resolve(promise), timeout]).finally(() => clearTimeout(timer));
}

// Wrap a supabase-js query so a withTimeout on it actually cancels the request
// instead of just giving up on the answer. Kept separate from withTimeout
// because not every awaitable it wraps is a query builder — Storage uploads,
// for one, take no signal in supabase-js v2.
function abortable(buildQuery) {
  const controller = new AbortController();
  const query = buildQuery(controller.signal);
  try { query[CLOUD_ABORT] = controller; } catch (_) { /* frozen thenable */ }
  return query;
}

// Is this the network giving out, as opposed to the server saying no? Only the
// former is worth retrying — replaying an RLS rejection or a schema error just
// burns time and ends in the same place. Matches the same shapes the reconcile
// catch already classifies as "offline".
function isTransientCloudError(error) {
  const message = String(error?.message || error || "");
  if (/failed to fetch|networkerror|load failed|timed out|aborted/i.test(message)) return true;
  // PostgREST/PostgreSQL surface real refusals with a code; those are final.
  return !error?.code && /network|connection|socket|econn|timeout/i.test(message);
}

// Retry an IDEMPOTENT cloud operation through a transient network failure.
// Every call site is a select, an upsert, or a delete-by-id — replaying any of
// them lands in the same final state, which is what makes this safe. A single
// dropped packet used to mark a whole deck "failed" for the run and leave the
// user to notice and re-sync by hand.
async function withRetry(operation, { tries = 2, baseMs = 500, label = "" } = {}) {
  let lastError;
  for (let attempt = 0; attempt < tries; attempt++) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
      if (attempt === tries - 1 || !isTransientCloudError(error)) throw error;
      // Don't sit through a backoff for a connection that's simply gone.
      if (!navigator.onLine) throw error;
      console.warn(`Retrying ${label || "cloud request"} after a transient failure`, error);
      await new Promise((resolve) => setTimeout(resolve, baseMs * (attempt + 1)));
    }
  }
  throw lastError;
}

// Run `worker` over `items` with at most `limit` in flight. Pushing decks one
// at a time meant a 20-deck sync paid 60+ sequential round trips — on a phone,
// almost all of it spent waiting rather than transferring. Results come back in
// input order. `worker` must never throw: each call site wraps its own body so
// one deck's failure is recorded and the rest continue.
async function mapWithConcurrency(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;
  const runners = new Array(Math.min(limit, items.length)).fill(null).map(async () => {
    while (true) {
      const index = next++;
      if (index >= items.length) return;
      results[index] = await worker(items[index], index);
    }
  });
  await Promise.all(runners);
  return results;
}

// Upsert one chunk of card rows, retrying without `category` if the database
// hasn't run supabase_setup.sql yet (no cards.category column). Mirrors
// the deck-level `notes` fallback: never lose card edits over a missing
// optional column.
async function upsertCardRows(rows) {
  if (!rows.length) return;
  // Retried on a transient network failure: an upsert of the same rows lands in
  // the same state, so replaying it is safe, and one dropped packet mid-sync
  // used to fail the whole deck.
  const upsert = (payload, label) => withRetry(
    () => withTimeout(abortable((signal) => supabaseClient.from("cards").upsert(payload).abortSignal(signal)), CLOUD_TIMEOUT_MS, label),
    { label }
  );
  const { error } = await upsert(rows, "save cards");
  if (!error) return;
  // Checked by PG error code first, exactly as isMissingNotesColumnError does.
  // Matching on the bare word "category" anywhere in the message could classify
  // an unrelated failure that merely mentions the column — a check constraint,
  // an RLS policy naming it — as "the migration hasn't run", silently strip the
  // categories out of the payload, and report the push as a clean success.
  if (!isMissingColumnError(error, "category")) throw error;
  console.warn("cards.category column missing — run supabase_setup.sql to sync quick-note categories");
  const stripped = rows.map(({ category: _omit, ...rest }) => rest);
  const { error: retryError } = await upsert(stripped, "save cards");
  if (retryError) throw retryError;
}

// Core cloud writer shared by the active-deck sync and the headless
// library-reconcile sync. Upserts the deck row and diff-upserts its cards from
// an explicit payload (never touches `state`). Throws on failure.
// `cards`: [{ id, question, answer, status, category }] in display order.
// `webCards`: this deck's existing cloud rows if the caller already fetched
// them (reconcileAllDecks fetches every deck's in one batched request), else
// null to fetch them here.
async function pushDeckRowsToCloud({ deckId, title, category, notes, meta, currentIndex, cards, isNewDeck, overwrite, now, webCards = null, say = () => {} }) {
  const deckData = {
    id: deckId,
    title,
    category,
    notes: notes || "",
    // Symmetric with the pull side (pullCloudDeckToLibrary), which already
    // reads cloud.meta generically for any deck — this was the missing half:
    // meta only ever reached Supabase via the quick_notes-scoped writers, so
    // a normal deck's meta (e.g. a synced reading position) never left the
    // device. Whole-column last-write-wins, same as notes; this does add one
    // more writer against that column alongside the quick-notes-scoped ones,
    // accepted as the same class of risk as two devices pushing concurrently.
    meta: meta && typeof meta === "object" ? meta : {},
    current_card_index: Number.isFinite(currentIndex) ? currentIndex : 0,
    updated_at: now,
    last_accessed_at: now
  };

  // Crash-safe ordering: write the deck row FIRST (a new deck's row must exist
  // to satisfy the cards.deck_id foreign key) but with a stale `updated_at`, so
  // an interrupted push leaves the deck looking un-synced and retriable rather
  // than "current" with missing cards. The real `now` timestamp is stamped last
  // (deckBumpData below), only after every card chunk has landed.
  const PENDING_TS = new Date(0).toISOString();
  const deckDataPending = { ...deckData, updated_at: PENDING_TS };

  let { error: deckError } = await withRetry(
    () => withTimeout(abortable((signal) => supabaseClient.from("decks").upsert(deckDataPending).abortSignal(signal)), CLOUD_TIMEOUT_MS, "save deck"),
    { label: "save deck" }
  );
  // This deck is NOT fully synced if we fall into this branch — cards may
  // still go through below, but the notes text stays cloud-side stale. The
  // caller must know that, not just see a console warning: this flag rides
  // in pushStats all the way to the sync report and the "Synced" pill, so the
  // deck stops silently reading as fully synced. See isMissingNotesColumnError
  // for why this is keyed on the error code, not a loose message match.
  let notesSyncFailed = false;
  if (deckError && isMissingNotesColumnError(deckError)) {
    // Database hasn't run supabase_setup.sql yet — sync everything else so
    // the user doesn't lose card changes, but warn about notes.
    const { notes: _omit, ...deckDataWithoutNotes } = deckDataPending;
    ({ error: deckError } = await withTimeout(abortable((signal) => supabaseClient.from("decks").upsert(deckDataWithoutNotes).abortSignal(signal)), CLOUD_TIMEOUT_MS, "save deck"));
    if (!deckError && String(notes || "").trim()) {
      notesSyncFailed = true;
      // A data-loss-relevant warning, unlike routine save-confirmation toasts
      // that only make sense for an explicit action — this must fire on a
      // background sync too, or it never reaches the user at all (the only
      // caller always pushes in the background).
      showToast("Notes not synced — run supabase_setup.sql in Supabase", "error");
    }
  }
  if (deckError) throw deckError;

  let webCardsById = new Map();
  let cardsDeleted = 0;
  if (overwrite) {
    say("Syncing... (2/3) Replacing existing web cards");
    const { error } = await withTimeout(abortable((signal) => supabaseClient.from("cards").delete().eq("deck_id", deckId).abortSignal(signal)), CLOUD_TIMEOUT_MS, "replace cards");
    if (error) throw error;
  } else if (!isNewDeck) {
    say("Syncing... (2/3) Checking for changes");
    let existing = webCards;
    if (!existing) {
      const { data, error } = await withTimeout(
        supabaseClient
          .from("cards")
          .select("id, question, answer, position, status, category")
          .eq("deck_id", deckId),
        CLOUD_TIMEOUT_MS,
        "read cards"
      );
      if (error) console.warn("Could not read cloud cards before push", deckId, error);
      existing = error ? null : data;
    }
    if (existing) {
      webCardsById = new Map(existing.map((wc) => [String(wc.id), wc]));
      const localIds = new Set(cards.map((c) => String(c.id)));
      const idsToDelete = existing.filter((wc) => !localIds.has(String(wc.id))).map((wc) => wc.id);
      cardsDeleted = idsToDelete.length;
      if (idsToDelete.length > 0) {
        const { error: deleteError } = await withTimeout(
          supabaseClient.from("cards").delete().eq("deck_id", deckId).in("id", idsToDelete),
          CLOUD_TIMEOUT_MS,
          "prune cards"
        );
        if (deleteError) throw deleteError;
      }
    }
  }

  // Tally WHICH kind of change each row represents, not just that it changed —
  // the report names them individually (see describeSyncStats).
  const pushStats = emptySyncStats();
  const cardsData = cards
    .map((card, index) => {
      const status = normalizeCardStatus(card.status);
      const category = card.category ? String(card.category) : null;
      const webCard = webCardsById.get(String(card.id));
      if (!webCard) {
        // isNewDeck/overwrite wiped the web side, so there's nothing to diff
        // against and every row legitimately counts as an addition.
        pushStats.cardsAdded += 1;
        return { id: card.id, deck_id: deckId, question: card.question, answer: card.answer, position: index, status, category, updated_at: now };
      }
      const edited = syncTextChanged(card.question, webCard.question) || syncTextChanged(card.answer, webCard.answer);
      const moved = Number(webCard.position) !== index;
      const restacked = normalizeCardStatus(webCard.status) !== status;
      const recategorised = (webCard.category || null) !== category;
      if (!edited && !moved && !restacked && !recategorised) return null;
      if (edited) pushStats.cardsEdited += 1;
      if (moved) pushStats.cardsMoved += 1;
      if (restacked) pushStats.statusChanges += 1;
      if (recategorised) pushStats.categoryChanges += 1;
      // `category` is sent on EVERY row, never conditionally. PostgREST requires
      // all objects in a bulk upsert to share one key set (PGRST102, "All object
      // keys must match"), so omitting it on the uncategorised rows failed the
      // whole batch for any deck with a mix — and made clearing a category
      // impossible to push. Databases without the column are handled by the
      // retry in upsertCardRows.
      return { id: card.id, deck_id: deckId, question: card.question, answer: card.answer, position: index, status, category, updated_at: now };
    })
    .filter(Boolean);

  say(`Syncing... (3/3) Saving ${cardsData.length} of ${cards.length} cards`);
  const chunkSize = 50;
  // Upload chunks sequentially — parallel Promise.all could leave the cloud
  // in a partial state if chunk N fails while chunk N+1 already succeeded,
  // silently dropping the cards in the failed chunk.
  for (let i = 0; i < cardsData.length; i += chunkSize) {
    await upsertCardRows(cardsData.slice(i, i + chunkSize));
  }

  // Every card is in — NOW advance the deck's `updated_at` (and last-accessed)
  // to the real timestamp. This is the last write of the push, so a crash any
  // time before here leaves the deck stamped at PENDING_TS and therefore
  // re-pushed on the next sync, never falsely current. The caller marks the
  // local deck's lastSyncedAt only after this whole function resolves, and it
  // throws on any failure above, so a partial push is never marked synced.
  const { error: bumpError } = await withTimeout(
    supabaseClient.from("decks").update({ updated_at: now, last_accessed_at: now }).eq("id", deckId),
    CLOUD_TIMEOUT_MS,
    "finalize deck"
  );
  if (bumpError) throw bumpError;

  pushStats.cardsDeleted = cardsDeleted;
  pushStats.notesSyncFailed = notesSyncFailed;
  return pushStats;
}


